<!-- 
  Similar to Populate Component 
  Except this takes in a conditions object and returns the value that matches the condition.
-->
<script>
  import { isEmpty } from '@splendidlabz/utils'
  import { onMount } from 'svelte'
  import { getValueFromBrowserStorage, getValueFromSource } from './get-value'

  export let prop = ''
  export let conditions = {}
  export let source = {}

  let value
  const list = prop.split('.')

  // If source is provided, draw from source
  if (!isEmpty(source)) {
    value = conditions[getValueFromSource({ source, list })]
  }

  // If source is not provided, draw from localStorage, sessionstorage or query parameters (in this order) — in this case client:load is required.
  if (isEmpty(source)) {
    onMount(async _ => {
      value = getValueFromBrowserStorage(list)
      value = conditions[value]
    })
  }
</script>

{#if value}
  {value}
{:else}
  {conditions.fallback}
{/if}
